"""Generate text from a trusted locally trained Elyntro checkpoint."""
import argparse
from pathlib import Path
import torch
from .config import ModelConfig
from .model import ElyntroLanguageModel
from .tokenizer import ByteTokenizer


def load_checkpoint(path, device):
    # Only load checkpoints generated by a trusted local training run.
    checkpoint = torch.load(path, map_location=device, weights_only=True)
    if checkpoint.get("format") != "elyntro-lm-v1" or checkpoint.get("tokenizer") != "utf8-byte-v1":
        raise ValueError("Unsupported checkpoint format or tokenizer")
    model = ElyntroLanguageModel(ModelConfig.from_dict(checkpoint["config"])).to(device)
    model.load_state_dict(checkpoint["model_state_dict"])
    model.eval()
    return model


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--checkpoint", type=Path, required=True)
    p.add_argument("--prompt", required=True)
    p.add_argument("--tokens", type=int, default=300)
    p.add_argument("--temperature", type=float, default=0.8)
    p.add_argument("--top-k", type=int, default=40)
    p.add_argument("--device", choices=("auto", "cpu", "cuda", "mps"), default="auto")
    a = p.parse_args()
    if a.tokens < 0: p.error("tokens must be >= 0")
    if a.device == "auto":
        device = "cuda" if torch.cuda.is_available() else ("mps" if getattr(torch.backends, "mps", None) and torch.backends.mps.is_available() else "cpu")
    else: device = a.device
    tokenizer = ByteTokenizer()
    model = load_checkpoint(a.checkpoint, device)
    ids = torch.tensor([tokenizer.encode(a.prompt, add_bos=True)], dtype=torch.long, device=device)
    output = model.generate(ids, max_new_tokens=a.tokens, temperature=a.temperature, top_k=a.top_k, eos_token_id=tokenizer.EOS)
    print(tokenizer.decode(output[0].tolist()))


if __name__ == "__main__":
    main()
